css:
.container {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  background: linear-gradient(45deg, #0037ff 25%, transparent 25%),
    linear-gradient(-45deg, #0e173a 25%, transparent 25%);
  background-size: 60px 60px;
  background-position:
    0 0,
    30px 30px;
  /* animation: move 20s linear infinite;  */
}

.container::before,
.container::after {
  content: "";
  position: absolute;
  inset: 0;
}

.container::before {
  background: radial-gradient(
    circle at 50% 50%,
    rgba(169, 188, 255, 0.2) 15%,
    transparent 25%
  );
  background-size: 40px 40px;
  animation: pulse 8s ease-in-out infinite;
}

.container::after {
  background: repeating-linear-gradient(
    90deg,
    transparent 0px,
    transparent 4px,
    rgba(255, 255, 255, 0.3) 4px,
    rgba(255, 255, 255, 0.3) 8px
  );
  mix-blend-mode: overlay;
}

@keyframes move {
  100% {
    background-position:
      1000px 1000px,
      1030px 1030px;
  }
}

@keyframes pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.8;
  }
  50% {
    transform: scale(1.2);
    opacity: 0.6;
  }
}
